import { memo, useEffect, useState } from "react";
import { toolRegistry } from "./tool-registry";
import { GenericTool } from "./generic-tool";
import { getToolStatus } from "../utils/format-tool";
import { cn } from "../utils/cn";
import { ToolRowBase } from "./tool-row-base";

export type SubagentToolProps = {
  part: any;
  nestedTools?: any[];
  chatStatus?: string;
};

const MAX_VISIBLE_TOOLS = 5;

function formatElapsedTime(ms: number): string {
  if (ms < 1000) return "";
  const seconds = Math.floor(ms / 1000);
  if (seconds < 60) return `${seconds}s`;
  const minutes = Math.floor(seconds / 60);
  const remainingSeconds = seconds % 60;
  if (remainingSeconds === 0) return `${minutes}m`;
  return `${minutes}m ${remainingSeconds}s`;
}

export const SubagentTool = memo(function SubagentTool({
  part,
  nestedTools = [],
  chatStatus,
}: SubagentToolProps) {
  const { isPending, isInterrupted } = getToolStatus(part, chatStatus);
  const description = part.input?.description || "";
  const [elapsedMs, setElapsedMs] = useState(0);
  const startedAt =
    (part.callProviderMetadata?.custom?.startedAt as number | undefined) ??
    (part.startedAt as number | undefined);
  const hasNestedTools = nestedTools.length > 0;
  const outputDuration =
    part.output?.totalDurationMs ||
    part.output?.duration ||
    part.output?.duration_ms;

  useEffect(() => {
    if (isPending && startedAt) {
      setElapsedMs(Date.now() - startedAt);
      const interval = setInterval(() => {
        setElapsedMs(Date.now() - startedAt);
      }, 1000);
      return () => clearInterval(interval);
    }
  }, [isPending, startedAt]);

  const subtitle = (() => {
    if (isPending && hasNestedTools) {
      const lastTool = nestedTools[nestedTools.length - 1];
      const meta = lastTool ? toolRegistry[lastTool.type] : null;
      if (meta) {
        const title = meta.title(lastTool);
        const subtitle = meta.subtitle?.(lastTool);
        return subtitle ? `${title} ${subtitle}` : title;
      }
    }

    if (!description) return "";
    return description.length > 60
      ? `${description.slice(0, 57)}...`
      : description;
  })();
  const elapsedTimeDisplay = formatElapsedTime(
    !isPending && outputDuration ? outputDuration : elapsedMs,
  );

  if (isInterrupted && !part.output) {
    return (
      <ToolRowBase completeLabel="Subagent interrupted" isAnimating={false} />
    );
  }

  return (
    <div className="an-tool-task">
      <ToolRowBase
        completeLabel="Completed Subagent"
        shimmerLabel="Running Subagent"
        isAnimating={isPending}
        detail={subtitle}
        expandable={hasNestedTools}
        trailingContent={
          elapsedTimeDisplay ? (
            <span className="font-normal tabular-nums shrink-0 text-an-foreground-muted/60">
              {elapsedTimeDisplay}
            </span>
          ) : undefined
        }
      >
        <div className="relative">
          {isPending && nestedTools.length > MAX_VISIBLE_TOOLS && (
            <div className="absolute inset-x-0 top-0 h-8 z-10 pointer-events-none bg-linear-to-b from-an-background to-transparent" />
          )}
          <div
            className={cn(
              nestedTools.length > 1 ? "space-y-2" : "space-y-0",
              isPending &&
                nestedTools.length > MAX_VISIBLE_TOOLS &&
                "overflow-y-auto max-h-[120px]",
            )}
          >
            {nestedTools.map((nestedPart, idx) => {
              const nestedMeta = toolRegistry[nestedPart.type];
              if (!nestedMeta) {
                return (
                  <ToolRowBase
                    key={idx}
                    completeLabel={
                      nestedPart.type?.replace("tool-", "") ?? "Tool"
                    }
                    isAnimating={false}
                  />
                );
              }
              const { isPending: nestedIsPending, isError: nestedIsError } =
                getToolStatus(nestedPart, chatStatus);
              return (
                <GenericTool
                  key={idx}
                  icon={nestedMeta.icon}
                  title={nestedMeta.title(nestedPart)}
                  subtitle={nestedMeta.subtitle?.(nestedPart)}
                  isPending={nestedIsPending}
                  isError={nestedIsError}
                />
              );
            })}
          </div>
        </div>
      </ToolRowBase>
    </div>
  );
});

import type React from "react";
import {
  IconSearch as Search,
  IconEye as Eye,
  IconFolderSearch as FolderSearch,
  IconGitBranch as GitBranch,
  IconTerminal2 as Terminal,
  IconCircleX as XCircle,
  IconFileCode as FileCode2,
  IconSparkles as Sparkles,
  IconGlobe as Globe,
  IconFilePlus as FilePlus,
  IconChecklist as ListTodo,
  IconLogout as LogOut,
} from "@tabler/icons-react";

export type ToolVariant = "simple" | "collapsible";

export type ToolMeta = {
  icon: React.ComponentType<{ className?: string }>;
  title: (part: any) => string;
  subtitle?: (part: any) => string;
  variant: ToolVariant;
};

function getDisplayPath(filePath: string): string {
  if (!filePath) return "";
  const prefixes = [
    "/project/sandbox/repo/",
    "/project/sandbox/",
    "/project/",
    "/workspace/",
  ];
  for (const prefix of prefixes) {
    if (filePath.startsWith(prefix)) return filePath.slice(prefix.length);
  }
  const worktreeMatch = filePath.match(
    /\.21st\/worktrees\/[^/]+\/[^/]+\/(.+)$/,
  );
  if (worktreeMatch) return worktreeMatch[1]!;
  if (filePath.startsWith("/")) {
    const parts = filePath.split("/");
    const rootIndicators = ["apps", "packages", "src", "lib", "components"];
    const rootIndex = parts.findIndex((p) => rootIndicators.includes(p));
    if (rootIndex > 0) return parts.slice(rootIndex).join("/");
  }
  return filePath;
}

function calculateDiffStats(oldString: string, newString: string) {
  const oldLines = oldString.split("\n");
  const newLines = newString.split("\n");
  const maxLines = Math.max(oldLines.length, newLines.length);
  let addedLines = 0;
  let removedLines = 0;
  for (let i = 0; i < maxLines; i++) {
    if (oldLines[i] !== undefined && newLines[i] !== undefined) {
      if (oldLines[i] !== newLines[i]) {
        removedLines++;
        addedLines++;
      }
    } else if (oldLines[i] !== undefined) {
      removedLines++;
    } else if (newLines[i] !== undefined) {
      addedLines++;
    }
  }
  return { addedLines, removedLines };
}

export const toolRegistry: Record<string, ToolMeta> = {
  "tool-Task": {
    icon: Sparkles,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      const subagentType = part.input?.subagent_type || "Agent";
      return isPending
        ? `Running ${subagentType}`
        : `${subagentType} completed`;
    },
    subtitle: (part) => {
      const desc = part.input?.description || "";
      return desc.length > 50 ? desc.slice(0, 47) + "..." : desc;
    },
    variant: "simple",
  },
  // Agent tool — renamed from "Task" in claude-agent-sdk 0.2.63+
  "tool-Agent": {
    icon: Sparkles,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      const subagentType = part.input?.subagent_type || "Agent";
      return isPending
        ? `Running ${subagentType}`
        : `${subagentType} completed`;
    },
    subtitle: (part) => {
      const desc = part.input?.description || "";
      return desc.length > 50 ? desc.slice(0, 47) + "..." : desc;
    },
    variant: "simple",
  },
  "tool-Skill": {
    icon: Sparkles,
    title: () => "Skill",
    subtitle: (part) => part.input?.skill || "",
    variant: "simple",
  },
  "tool-Grep": {
    icon: Search,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      if (isPending) return "Grepping";
      const numFiles = part.output?.numFiles || 0;
      return numFiles > 0 ? `Grepped ${numFiles} files` : "No matches";
    },
    subtitle: (part) => {
      const pattern = part.input?.pattern || "";
      const path = part.input?.path || "";
      if (path) {
        const combined = `${pattern} in ${getDisplayPath(path)}`;
        return combined.length > 40 ? combined.slice(0, 37) + "..." : combined;
      }
      return pattern.length > 40 ? pattern.slice(0, 37) + "..." : pattern;
    },
    variant: "simple",
  },
  "tool-Glob": {
    icon: FolderSearch,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      if (isPending) return "Exploring files";
      const numFiles = part.output?.numFiles || 0;
      return numFiles > 0 ? `Found ${numFiles} files` : "No files found";
    },
    subtitle: (part) => {
      const pattern = part.input?.pattern || "";
      return pattern.length > 40 ? pattern.slice(0, 37) + "..." : pattern;
    },
    variant: "simple",
  },
  "tool-Read": {
    icon: Eye,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      return isPending ? "Reading" : "Read";
    },
    subtitle: (part) => {
      const filePath = part.input?.file_path || "";
      if (!filePath) return "";
      return filePath.split("/").pop() || "";
    },
    variant: "simple",
  },
  "tool-Edit": {
    icon: FileCode2,
    title: (part) => {
      const filePath = part.input?.file_path || "";
      if (!filePath) return "Edit";
      return filePath.split("/").pop() || "Edit";
    },
    subtitle: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      if (isPending) return "";
      const oldString = part.input?.old_string || "";
      const newString = part.input?.new_string || "";
      if (!oldString && !newString) return "";
      if (oldString !== newString) {
        const { addedLines, removedLines } = calculateDiffStats(
          oldString,
          newString,
        );
        return `+${addedLines} -${removedLines}`;
      }
      return "";
    },
    variant: "simple",
  },
  "tool-Write": {
    icon: FilePlus,
    title: () => "Create",
    subtitle: (part) => {
      const filePath = part.input?.file_path || "";
      if (!filePath) return "";
      return filePath.split("/").pop() || "";
    },
    variant: "simple",
  },
  "tool-Bash": {
    icon: Terminal,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      return isPending ? "Running command" : "Ran command";
    },
    subtitle: (part) => {
      const command = part.input?.command || "";
      if (!command) return "";
      let normalized = command.replace(/\\\s*\n\s*/g, " ").trim();
      normalized = normalized.replace(
        /\/(?:Users|home|root)\/[^\s"']+/g,
        (match: string) => getDisplayPath(match),
      );
      return normalized.length > 50
        ? normalized.slice(0, 47) + "..."
        : normalized;
    },
    variant: "simple",
  },
  "tool-WebFetch": {
    icon: Globe,
    title: (part) => {
      const isPending =
        part.state !== "output-available" && part.state !== "output-error";
      return isPending ? "Fetching" : "Fetched";
    },
    subtitle: (part) => {
      const url = part.input?.url || "";
      try {
        return new URL(url).hostname.replace("www.", "");
      } catch {
        return url.slice(0, 30);
      }
